<script setup lang="ts">
import { onMounted, ref } from 'vue'
import UserTopbar from '@/components/UserTopbar.vue'
import { getCourses, type Course } from '@/api/courses'

const records = ref<Course[]>([]); const total = ref(0); const page = ref(1); const loading = ref(false); const keyword = ref(''); const danceType = ref(''); const difficulty = ref('')
async function load() { loading.value = true; try { const result = await getCourses({ page: page.value, pageSize: 9, keyword: keyword.value || undefined, danceType: danceType.value || undefined, difficulty: difficulty.value || undefined }); records.value = result.data.records; total.value = result.data.total } finally { loading.value = false } }
function search() { page.value = 1; load() }
onMounted(load)
</script>

<template>
  <main class="courses-page"><UserTopbar />
    <section class="hero"><p class="eyebrow">DANCE ACADEMY</p><h1>把每一次练习，变成身体的记忆。</h1><p>按舞种和难度找到适合你的课程，从基础律动开始持续进步。</p></section>
    <section class="toolbar"><el-input v-model="keyword" clearable placeholder="搜索课程或老师" @keyup.enter="search" /><el-select v-model="danceType" clearable placeholder="全部舞种"><el-option label="Hip-hop" value="Hip-hop" /><el-option label="Jazz Funk" value="Jazz Funk" /><el-option label="Performance" value="Performance" /></el-select><el-select v-model="difficulty" clearable placeholder="全部难度"><el-option label="入门" value="BEGINNER" /><el-option label="进阶" value="INTERMEDIATE" /><el-option label="高级" value="ADVANCED" /></el-select><el-button type="primary" @click="search">搜索</el-button></section>
    <section v-loading="loading" class="course-grid"><el-empty v-if="!loading && !records.length" description="暂无已发布课程" /><article v-for="course in records" :key="course.id" class="course-card" @click="router.push(`/courses/${course.id}`)"><div class="cover"><span>{{ course.danceType }}</span><strong>{{ course.difficulty === 'BEGINNER' ? '入门' : course.difficulty === 'INTERMEDIATE' ? '进阶' : '高级' }}</strong></div><div class="card-body"><p class="teacher">{{ course.teacherName }} · {{ course.lessonCount }} 个课时</p><h2>{{ course.title }}</h2><p>{{ course.description || '跟随老师完成一套系统的舞蹈训练。' }}</p><el-button link type="primary">开始学习 →</el-button></div></article></section><el-pagination v-if="total" v-model:current-page="page" layout="prev, pager, next" :page-size="9" :total="total" @current-change="load" />
  </main>
</template>

