@media (max-width: 760px) { .topbar { padding: 0 18px; }.topbar nav { gap: 10px; }.hero { padding-top: 48px; }.toolbar { flex-wrap: wrap; }.toolbar .el-input { max-width: none; width: 100%; }.course-grid { grid-template-columns: repeat(2, 1fr); } } @media (max-width: 520px) { .course-grid { grid-template-columns: 1fr; } }
